import React, { Component } from "react";
import "./Aboutus.css";
import PagesJson from "./PagesJson";

export default class Aboutus extends Component {
      constructor(props) {
        super(props);
        this.state = {
          aboutus: null,
        };
      }

      componentDidMount(){
        fetch('http://localhost:3001/${PageName}')
        .then(response => response.json())
        .then(pages => {
          const aboutus = pages.find(page => page.PageName === "About Us");
          this.setState({ aboutus});

        })
          .catch(error => console.error('Error fetching data:', error));
      }
      render() {
const {aboutus}=this.state;
if(aboutus) return <div>PAGEFOUND</div>;
      const contentAbout = aboutus.content;

        return (
            <div className="about-containerr">
              <div className="about-rectangle">
                <h1 className="TaiLink-About">{contentAbout.title}</h1>
                <div className="sen1">
                  {contentAbout.map((item) => (
                    <>
                    <p>
                        {item.p}
                    </p>
                    </>
                  ))}
                </div>
              </div>
            </div>
          );
        };
    }
